import csv
import sys
from collections import Counter


def count_nonempty(csv_path: str) -> Counter:
    counts = Counter()
    with open(csv_path, newline="", encoding="utf-8-sig") as f:
        reader = csv.reader(f)
        header = next(reader, [])
        counts.update(header)
        for row in reader:
            for i, value in enumerate(row):
                if i < len(header) and value.strip():
                    counts[header[i]] += 1
    return counts


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print(f"用法: python {sys.argv[0]} <csv文件>")
        sys.exit(1)
    for col, n in count_nonempty(sys.argv[1]).items():
        print(f"{col}: {n}")
